True def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) >= 4:
                boxes.append((min(y for y, x in cells), max(y for y, x in cells), min(x for y, x in cells), max(x for y, x in cells)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0, r1, c0, c1 in boxes):
                for y in range(max(0, r - 1), min(h, r + 2)):
                    for x in range(max(0, c - 1), min(w, c + 2)):
                        if grid[y][x] != 2:
                            out[y][x] = 1
    return out
